postings = {
    'vector': [1, 2, 5, 9, 14],
    'index':  [2, 5, 7, 14, 20],
}

def intersect(a, b):  # two-pointer merge over sorted lists
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            out.append(a[i]); i += 1; j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return out

print('docs with both terms:', intersect(postings['vector'], postings['index']))

def encode(n):
    out = bytearray()
    while True:
        chunk = n & 0x7F
        n >>= 7
        if n:
            out.append(chunk)          # continuation: high bit clear
        else:
            out.append(chunk | 0x80)   # final chunk: high bit set
            return bytes(out)

def decode(buf):
    n, shift = 0, 0
    for b in buf:
        n |= (b & 0x7F) << shift
        if b & 0x80:
            return n
        shift += 7

for v in (5, 127, 128, 1000, 1000000):
    enc = encode(v)
    print('%7d -> %d byte(s), decodes to %d' % (v, len(enc), decode(enc)))

# Roaring idea: group by high 16 bits, pick container type by density.
CONTAINERS = {}

def add(x):
    hi, lo = x >> 16, x & 0xFFFF
    c = CONTAINERS.setdefault(hi, {'kind': 'array', 'vals': set()})
    c['vals'].add(lo)
    if len(c['vals']) > 4096:
        c['kind'] = 'bitmap'  # dense -> switch representation

sparse = list(range(0, 1000, 7))
dense = list(range(200000, 210000))
for x in sparse + dense:
    add(x)
for hi, c in sorted(CONTAINERS.items()):
    print('container high=%d: kind=%-6s members=%d' % (hi, c['kind'], len(c['vals'])))

# A trie shows the FST idea: shared prefixes stored once.
terms = {'vector': 0, 'vectors': 1, 'version': 2, 'vertex': 3}
trie = {}
for term, off in terms.items():
    node = trie
    for ch in term:
        node = node.setdefault(ch, {})
    node['$'] = off  # terminal: postings offset

def lookup(term):
    node = trie
    for ch in term:
        if ch not in node:
            return None
        node = node[ch]
    return node.get('$')

print('vector ->', lookup('vector'), '| version ->', lookup('version'))
print('missing ->', lookup('vapor'))
print('shared prefix "ve" stored once for', sum(t.startswith('ve') for t in terms), 'terms')
